func:
// Mail gönderme parametrelerini burada ayarlayın

// Alıcı email adresi
msg.to = "serkan.meral@outlook.com";

// Mail konusu
msg.subject = "Test Mail from Node-RED - MonitraNG";

// Mail içeriği (Plain Text)
msg.text = "Bu bir test mailidir.\n\nNode-RED flow'undan gönderilmiştir.";

// Mail içeriği (HTML formatında - opsiyonel)
// HTML kullanıyorsanız, text yerine html kullanın
msg.html = `
    <html>
        <body>
            <h2>Test Mail from Node-RED</h2>
            <p>Bu bir test mailidir.</p>
            <p>Node-RED flow'undan gönderilmiştir.</p>
            <hr>
            <p><small>MonitraNG Mail Server</small></p>
        </body>
    </html>
`;

// Gönderen adresi (noreply@monitrang.com)
msg.from = "noreply@monitrang.com";

// Gönderen adı (opsiyonel)
msg.fromName = "MonitraNG";

return msg;

// HTTP POST request'inden gelen parametreleri işle

// Request body'den parametreleri al
const body = msg.payload;

// Alıcı email adresi (zorunlu)
msg.to = body.to || "serkan.meral@outlook.com";

// Mail konusu (zorunlu)
msg.subject = body.subject || "Mail from Node-RED - MonitraNG";

// Mail içeriği (Plain Text)
msg.text = body.text || body.message || "";

// Mail içeriği (HTML formatında - opsiyonel)
if (body.html) {
    msg.html = body.html;
}

// Gönderen adresi (noreply@monitrang.com)
msg.from = "noreply@monitrang.com";

// Gönderen adı (opsiyonel)
msg.fromName = body.fromName || "MonitraNG";

return msg;
